import Dexie, { type Table } from 'dexie'

class AppDB extends Dexie {
  drafts!: Table<{ id: string; body: string; updatedAt: number }>
  constructor() {
    super('app')
    this.version(1).stores({ drafts: 'id, updatedAt' })
  }
}
const db = new AppDB()

db.on('versionchange', () => {
  db.close()
  location.reload() // another tab upgraded the schema
})

await db.drafts.put({ id: 'doc-1', body, updatedAt: Date.now() })

