// Register, then ask the user before skipWaiting.
navigator.serviceWorker.addEventListener('controllerchange', () => {
  // a new SW now controls this page — reload once
})

async function promptUpdate(reg: ServiceWorkerRegistration) {
  const waiting = reg.waiting
  if (!waiting) return
  showBanner('A new version is ready', () => {
    waiting.postMessage({ type: 'SKIP_WAITING' })
  })
}

reg.addEventListener('updatefound', () => promptUpdate(reg))

