const bus = new BroadcastChannel('session')

export function useSessionBus() {
  function endSession() {
    userStore.clear()
    queryClient.clear()
    bus.postMessage({ type: 'session:end' })
    router.push('/login')
  }
  function onMessage(e: MessageEvent<{ type: string }>) {
    if (e.data.type === 'session:end') {
      inflight.abort()
      userStore.clear()
      router.push('/login')
    }
  }
  bus.addEventListener('message', onMessage)
  onScopeDispose(() => bus.removeEventListener('message', onMessage))
  return { endSession }
}

